INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 20, 'theory', 'Квиз: CSS — Grid');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 0, 'Чем грид принципиально отличается от флексбокса?', '["Грид работает только с таблицами данных","Грид раскладывает элементы по двум осям сразу — строкам и колонкам, а флексбокс — вдоль одной оси","Флексбокс умеет задавать промежутки, а грид — нет","Грид включается только внутри медиа-запроса"]', 1, 'Флексбокс одномерный: ряд или столбец, размеры диктует содержимое. Грид двумерный: контейнер описывает и строки, и колонки, а элементы встают в ячейки. Промежутки gap есть у обоих.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 1, 'Что означает grid-template-columns: 200px 1fr 2fr?', '["Три колонки по 200 пикселей","Три равные колонки","Колонка 200px и две колонки, которые делят остаток поровну","Колонка 200px и две колонки, которые делят остаток в отношении один к двум"]', 3, 'Сначала вычитаются фиксированные размеры и промежутки, остаток делится по долям: одна доля и две доли. Вторая колонка получается вдвое уже третьей.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 2, 'Что делает repeat(auto-fit, minmax(200px, 1fr))?', '["Ставит столько колонок шириной не меньше 200px, сколько помещается в строку, и растягивает их на всю ширину","Всегда создаёт ровно одну колонку шириной 200px","Создаёт две колонки: 200px и одну долю","Работает только вместе с медиа-запросами для каждой ширины окна"]', 0, 'Браузер сам считает число колонок по минимуму 200px, а остаток делит поровну через 1fr. Так сетка перестраивается без единого медиа-запроса. Auto-fill отличается тем, что сохраняет пустые дорожки.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 3, 'Что означает grid-column: 1 / -1?', '["Элемент занимает только первую колонку","Элемент скрывается из сетки","Элемент тянется от первой до последней линии явной сетки, то есть на всю строку","Элемент занимает колонку с номером минус один"]', 2, 'Линии нумеруются с единицы слева направо, а отрицательные номера отсчитываются с конца: минус первая — последняя линия явной сетки. Запись работает при любом числе колонок.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 20, 4, 'Чем place-items отличается от place-content?', '["place-items двигает всю сетку, а place-content выравнивает содержимое ячеек","place-items выравнивает элементы внутри ячеек, а place-content двигает саму сетку внутри контейнера","Это два названия одного и того же свойства","place-items работает только у флексбокса, а place-content — только у грида"]', 1, 'Items — про содержимое ячеек (align-items и justify-items), content — про положение дорожек в контейнере, когда они занимают не всё место. Для одного элемента есть align-self и justify-self.');
